  if (c.labGo) { c.driver = 'ai'; c.ln = null; c.labGo = false; }
  qburst(c.x, c.y, '#3cf0ff'); qburst(o.x, o.y, '#3cf0ff'); sfx.quantum();
  msg('Entangled with that car. Press T again to measure the pair and swap places with it.', 3.5);
