  const A = { x: o.x, y: o.y, angle: me ? me.angle : player.angle, vx: o.vx || 0, vy: o.vy || 0, speed: me ? me.speed : 0 };
  const B = { x: c.x, y: c.y, angle: c.angle, vx: c.vx, vy: c.vy, speed: c.speed };
