  player.hp = 0; player.down = 4; player.downKind = 'wasted';
  if (!lab) player.lives--;
  bigText('WASTED', '#e74c3c', 4, lab ? 'the lesson restarts' : player.lives > 0 ? `${player.lives} ${player.lives === 1 ? 'life' : 'lives'} left` : '');
  addDecal({ k: 'blood', x: player.x, y: player.y, r: 12 });
