  smg:    { c: '#95a5a6', l: 'M', label: 'Machine Gun +120', give: () => give('smg', 120) },
  rocket: { c: '#e74c3c', l: 'R', label: 'Rocket Launcher +5', give: () => give('rocket', 5) },
