    const t = randomTile([WALK, PLAZA, GRASS, SAND], p => !inCity(p.tx, p.ty) && !taken[p.ty * MW + p.tx] && (!BRNO || DISTRICTS[REG[p.ty * MW + p.tx]].kind !== 'city'));
